        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint256 afterFirst;
        try c.getBalance(address(this)) returns (uint256 __r) { afterFirst = __r; } catch { return; }
        bool reverted2;
        try c.withdrawBalance() { reverted2 = false; } catch { reverted2 = true; }
        uint256 afterSecond;
        try c.getBalance(address(this)) returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue(afterFirst == 0 && !reverted2 && afterSecond == 0);
